class Solution {
public:
    ListNode* reverse(ListNode* head) {
        ListNode* prev = nullptr;
        ListNode* curr = head;
        while (curr) {
            ListNode* next = curr->next;
            curr->next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }

    ListNode* removeNodes(ListNode* head) {
        head = reverse(head);
        int maxVal = 0;
        ListNode* curr = head;
        ListNode* prev = nullptr;
        while (curr) {
            if (curr->val < maxVal) {
                prev->next = curr->next;
            } else {
                maxVal = curr->val;
                prev = curr;
            }
            curr = curr->next;
        }
        head = reverse(head);
        return head;
    }
};
